#!/usr/bin/env python3
"""Minimal ANSI terminal emulator: render raw pty bytes to a screen dump.

Usage: render.py raw.bin [--rows R] [--cols C] [--styles]
Prints the screen text; with --styles also prints a per-cell style map.
"""
import sys, argparse, re

class Cell:
    __slots__ = ("ch", "fg", "bg", "attrs")
    def __init__(self):
        self.ch = " "; self.fg = "d"; self.bg = "d"; self.attrs = frozenset()

class Term:
    def __init__(self, rows, cols):
        self.rows, self.cols = rows, cols
        self.alt = False
        self.screens = {False: self._blank(), True: self._blank()}
        self.x = self.y = 0
        self.fg = "d"; self.bg = "d"; self.attrs = set()
        self.wrap = True
    def _blank(self):
        return [[Cell() for _ in range(self.cols)] for _ in range(self.rows)]
    @property
    def buf(self):
        return self.screens[self.alt]
    def put(self, ch, w=1):
        if self.x >= self.cols:
            if self.wrap:
                self.x = 0; self.y = min(self.y+1, self.rows-1)
            else:
                self.x = self.cols-1
        c = self.buf[self.y][self.x]
        c.ch = ch; c.fg = self.fg; c.bg = self.bg; c.attrs = frozenset(self.attrs)
        self.x += 1
        for _ in range(w-1):
            if self.x < self.cols:
                c2 = self.buf[self.y][self.x]
                c2.ch = ""; c2.fg = self.fg; c2.bg = self.bg; c2.attrs = frozenset(self.attrs)
                self.x += 1
    def sgr(self, params):
        if not params: params = [0]
        i = 0
        while i < len(params):
            p = params[i]
            if p == 0:
                self.fg = "d"; self.bg = "d"; self.attrs = set()
            elif p == 1: self.attrs.add("bold")
            elif p == 2: self.attrs.add("dim")
            elif p == 3: self.attrs.add("italic")
            elif p == 4: self.attrs.add("underline")
            elif p == 5: self.attrs.add("blink")
            elif p == 7: self.attrs.add("inverse")
            elif p == 9: self.attrs.add("strike")
            elif p == 21 or p == 22: self.attrs.discard("bold"); self.attrs.discard("dim")
            elif p == 23: self.attrs.discard("italic")
            elif p == 24: self.attrs.discard("underline")
            elif p == 25: self.attrs.discard("blink")
            elif p == 27: self.attrs.discard("inverse")
            elif p == 29: self.attrs.discard("strike")
            elif 30 <= p <= 37: self.fg = str(p-30)
            elif p == 39: self.fg = "d"
            elif 40 <= p <= 47: self.bg = str(p-40)
            elif p == 49: self.bg = "d"
            elif 90 <= p <= 97: self.fg = "b%d" % (p-90)
            elif 100 <= p <= 107: self.bg = "b%d" % (p-100)
            elif p in (38, 48):
                tgt = "fg" if p == 38 else "bg"
                if i+1 < len(params) and params[i+1] == 5:
                    val = "c%d" % params[i+2]; i += 2
                elif i+1 < len(params) and params[i+1] == 2:
                    val = "r%d,%d,%d" % (params[i+2], params[i+3], params[i+4]); i += 4
                else:
                    val = "?"
                setattr(self, tgt, val)
            i += 1
    def feed(self, data):
        i = 0; n = len(data)
        while i < n:
            b = data[i]
            if b == 0x1b:
                if i+1 >= n: break
                c = data[i+1]
                if c == 0x5b:  # [
                    j = i+2
                    while j < n and (0x20 <= data[j] <= 0x3f):
                        j += 1
                    if j >= n: break
                    final = data[j]
                    body = data[i+2:j].decode("latin1")
                    self.csi(final, body)
                    i = j+1; continue
                elif c == 0x50 or c == 0x5d or c == 0x58 or c == 0x5e or c == 0x5f:
                    # DCS/OSC/... until ST (ESC \) or BEL
                    j = i+2
                    while j < n:
                        if data[j] == 0x07: j += 1; break
                        if data[j] == 0x1b and j+1 < n and data[j+1] == 0x5c: j += 2; break
                        j += 1
                    i = j; continue
                elif c == 0x28 or c == 0x29:
                    i += 3; continue
                else:
                    i += 2; continue
            elif b == 0x0d:
                self.x = 0; i += 1; continue
            elif b == 0x0a:
                self.y += 1
                if self.y >= self.rows:
                    self.y = self.rows-1
                    self.buf.pop(0); self.buf.append([Cell() for _ in range(self.cols)])
                i += 1; continue
            elif b == 0x08:
                self.x = max(0, self.x-1); i += 1; continue
            elif b == 0x09:
                self.x = min(self.cols-1, (self.x//8+1)*8); i += 1; continue
            elif b == 0x00 or b == 0x07:
                i += 1; continue
            else:
                # utf8 decode
                ln = 1
                if b >= 0xf0: ln = 4
                elif b >= 0xe0: ln = 3
                elif b >= 0xc0: ln = 2
                ch = data[i:i+ln].decode("utf-8", errors="replace")
                w = 1
                cp = ord(ch[0]) if ch else 32
                if (0x1100 <= cp <= 0x115f or 0x2e80 <= cp <= 0xa4cf or 0xac00 <= cp <= 0xd7a3
                    or 0xf900 <= cp <= 0xfaff or 0xfe30 <= cp <= 0xfe6f or 0xff00 <= cp <= 0xff60
                    or 0xffe0 <= cp <= 0xffe6 or 0x1f300 <= cp <= 0x1f9ff or 0x20000 <= cp <= 0x3fffd):
                    w = 2
                self.put(ch, w)
                i += ln; continue
    def csi(self, final, body):
        priv = body.startswith("?")
        raw = body[1:] if priv else body
        if raw.startswith(">") or raw.startswith("$"):
            return
        try:
            params = [int(x) if x else 0 for x in raw.split(";")] if raw else []
        except ValueError:
            params = []
        f = chr(final)
        def p(idx, dflt=1):
            return params[idx] if idx < len(params) and params[idx] != 0 else dflt
        if priv:
            if f == "h":
                for v in params:
                    if v == 1049: self.alt = True; self.x=self.y=0
                    elif v == 7: self.wrap = True
            elif f == "l":
                for v in params:
                    if v == 1049: self.alt = False
                    elif v == 7: self.wrap = False
            return
        if f == "m": self.sgr(params)
        elif f == "A": self.y = max(0, self.y - p(0))
        elif f == "B": self.y = min(self.rows-1, self.y + p(0))
        elif f == "C": self.x = min(self.cols-1, self.x + p(0))
        elif f == "D": self.x = max(0, self.x - p(0))
        elif f == "E": self.y = min(self.rows-1, self.y+p(0)); self.x = 0
        elif f == "F": self.y = max(0, self.y-p(0)); self.x = 0
        elif f == "G": self.x = min(self.cols-1, p(0)-1)
        elif f == "d": self.y = min(self.rows-1, p(0)-1)
        elif f in ("H", "f"):
            self.y = min(self.rows-1, p(0)-1); self.x = min(self.cols-1, p(1)-1)
        elif f == "J":
            mode = params[0] if params else 0
            if mode == 2 or mode == 3:
                self.screens[self.alt] = self._blank()
            elif mode == 0:
                for xx in range(self.x, self.cols): self.buf[self.y][xx] = Cell()
                for yy in range(self.y+1, self.rows): self.buf[yy] = [Cell() for _ in range(self.cols)]
            else:
                for xx in range(0, self.x+1): self.buf[self.y][xx] = Cell()
                for yy in range(0, self.y): self.buf[yy] = [Cell() for _ in range(self.cols)]
        elif f == "K":
            mode = params[0] if params else 0
            if mode == 0:
                for xx in range(self.x, self.cols): self.buf[self.y][xx] = Cell()
            elif mode == 1:
                for xx in range(0, self.x+1): self.buf[self.y][xx] = Cell()
            else:
                self.buf[self.y] = [Cell() for _ in range(self.cols)]
        elif f == "L":
            cnt = p(0)
            for _ in range(cnt):
                self.buf.insert(self.y, [Cell() for _ in range(self.cols)])
                self.buf.pop()
        elif f == "M":
            cnt = p(0)
            for _ in range(cnt):
                self.buf.pop(self.y)
                self.buf.append([Cell() for _ in range(self.cols)])

    def dump(self):
        out = []
        for row in self.buf:
            s = "".join(c.ch for c in row)
            out.append(s.rstrip())
        return "\n".join(out)

    def style_dump(self):
        """Compact run-length style map per row."""
        lines = []
        for y, row in enumerate(self.buf):
            runs = []
            cur = None; start = 0
            for x, c in enumerate(row):
                key = (c.fg, c.bg, tuple(sorted(c.attrs)))
                if key != cur:
                    if cur is not None and (cur[0] != "d" or cur[1] != "d" or cur[2]):
                        runs.append("%d-%d:%s/%s/%s" % (start, x-1, cur[0], cur[1], ",".join(cur[2])))
                    cur = key; start = x
            if cur is not None and (cur[0] != "d" or cur[1] != "d" or cur[2]):
                runs.append("%d-%d:%s/%s/%s" % (start, self.cols-1, cur[0], cur[1], ",".join(cur[2])))
            if runs:
                lines.append("L%02d %s" % (y, " ".join(runs)))
        return "\n".join(lines)

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("file")
    ap.add_argument("--rows", type=int, default=30)
    ap.add_argument("--cols", type=int, default=90)
    ap.add_argument("--styles", action="store_true")
    ap.add_argument("--ruler", action="store_true")
    a = ap.parse_args()
    t = Term(a.rows, a.cols)
    t.feed(open(a.file, "rb").read())
    d = t.dump()
    if a.ruler:
        tens = "".join(str((i//10)%10) for i in range(a.cols))
        ones = "".join(str(i%10) for i in range(a.cols))
        print("    " + tens); print("    " + ones)
        for i, line in enumerate(d.split("\n")):
            print("%3d|%s" % (i, line))
    else:
        print(d)
    if a.styles:
        print("--- STYLES ---")
        print(t.style_dump())

main()

