#!/usr/bin/env python3
"""Parse the caps-log screen: focus, menus, calendar day styles."""
import sys, argparse, re
src=open("/workspace/notes/render.py").read().replace("\nmain()\n","\n")
ns={}; exec(compile(src,"r","exec"),ns); Term=ns["Term"]

MONTHS=["January","February","March","April","May","June","July","August","September","October","November","December"]

def load(f,rows=60,cols=200):
    t=Term(rows,cols); t.feed(open(f,"rb").read()); return t

def analyze(t,rows,cols,show_days=True):
    B=t.buf
    def txt(y,c0,c1): return "".join(B[y][x].ch for x in range(c0,min(c1,cols-1)+1))
    res={}
    # header
    for y in range(rows):
        s=txt(y,0,cols-1)
        if "Today is:" in s: res["header"]=s.strip(); res["header_line"]=y
    # boxes
    def find(title):
        for y in range(rows):
            s=txt(y,0,cols-1)
            i=s.find("╭"+title)
            if i>=0: return y,i
        return None,None
    sy,sx=find("Sections"); ty,tx=find("Tags")
    res["boxes"]=(sy,sx,ty,tx)
    def menu(y0,x0):
        s=txt(y0,x0,cols-1); w=s.find("╮")+1
        out=[]; yy=y0+1
        while yy<rows:
            line=txt(yy,x0,x0+w-1)
            if line.startswith("╰"): break
            inner=line[1:-1]
            runs=[];cur=None;st=0
            for i,ch in enumerate(inner):
                c=B[yy][x0+1+i]; k=(c.fg,c.bg,tuple(sorted(c.attrs)))
                if k!=cur:
                    if cur is not None: runs.append((st,i-1,cur))
                    cur=k;st=i
            runs.append((st,len(inner)-1,cur))
            out.append((yy,inner,runs))
            yy+=1
        return w,out,B[y0][x0]
    res["sections"]=menu(sy,sx) if sy is not None else None
    res["tags"]=menu(ty,tx) if ty is not None else None
    # calendar: find month boxes
    days={}
    for y in range(rows):
        s=txt(y,0,cols-1)
        for m,name in enumerate(MONTHS,1):
            for mt in re.finditer("╭"+name+"─",s):
                x0=mt.start()
                # weekday header row is y+1, day rows y+2..
                for yy in range(y+2,y+9):
                    if yy>=rows: break
                    line=txt(yy,x0+1,x0+21)
                    if line.startswith("╰") or line.startswith("─"): break
                    for dm in re.finditer(r"\d+", line):
                        d=int(dm.group())
                        ax=x0+1+dm.start()
                        cells=[B[yy][ax+k] for k in range(len(dm.group()))]
                        k=(cells[0].fg,cells[0].bg,tuple(sorted(cells[0].attrs)))
                        days[(m,d)]=(yy,ax,k)
    res["days"]=days
    return res

def fmt_style(k): return "%s/%s/%s"%(k[0],k[1],",".join(k[2]))

def report(f,rows=60,cols=200,cal=True,menus=True):
    t=load(f,rows,cols); r=analyze(t,rows,cols)
    print(r.get("header","<no header>"))
    if menus:
        for nm in ("sections","tags"):
            w,items,bc=r[nm]
            print("[%s] boxw=%d borderdim=%s"%(nm,w,"dim" in bc.attrs))
            for (y,inner,runs) in items:
                if inner.strip()=="": continue
                print("   L%02d |%s| %s"%(y,inner," ".join("(%d-%d %s)"%(s,e,fmt_style(k)) for s,e,k in runs)))
    if cal:
        groups={}
        for (m,d),(y,x,k) in sorted(r["days"].items()):
            groups.setdefault(fmt_style(k),[]).append("%02d-%02d"%(m,d))
        for k,v in sorted(groups.items(), key=lambda kv:-len(kv[1])):
            if len(v)>40: print("  CAL %s : <%d days> (baseline)"%(k,len(v)))
            else: print("  CAL %s : %s"%(k," ".join(v)))
if __name__=="__main__":
    ap=argparse.ArgumentParser(); ap.add_argument("file"); ap.add_argument("--rows",type=int,default=60); ap.add_argument("--cols",type=int,default=200)
    ap.add_argument("--nocal",action="store_true"); ap.add_argument("--nomenus",action="store_true")
    a=ap.parse_args(); report(a.file,a.rows,a.cols,not a.nocal, not a.nomenus)
