#!/usr/bin/env python3
"""Like drive.py but records byte offsets after each key so we can snapshot each step."""
import os,sys,pty,time,select,termios,struct,fcntl,argparse,json,signal
def set_size(fd,rows,cols): fcntl.ioctl(fd,termios.TIOCSWINSZ,struct.pack("HHHH",rows,cols,0,0))
KEYMAP={"<up>":"\x1b[A","<down>":"\x1b[B","<right>":"\x1b[C","<left>":"\x1b[D","<enter>":"\r","<tab>":"\t","<stab>":"\x1b[Z","<esc>":"\x1b","<bs>":"\x7f","<space>":" ","<home>":"\x1b[H","<end>":"\x1b[F","<pgup>":"\x1b[5~","<pgdn>":"\x1b[6~","<del>":"\x1b[3~","<ctrl-c>":"\x03","<ctrl-d>":"\x04"}
def parse_keys(s):
    out=[];i=0
    while i<len(s):
        if s[i]=="<":
